package az.iktex.organization.structure.testders.repository;
import az.iktex.organization.structure.testders.entity.Student; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface StudentRepository extends JpaRepository<Student,Long> { @Query("select s from Student s where s.courses is empty") List<Student> findWithoutCourses(); boolean existsByIdAndCoursesId(Long studentId,Long courseId); List<Student> findAllBySurname(String surname); @Query("select distinct s from Student s left join fetch s.courses where s.id=:id") Optional<Student> findDetailById(@Param("id") Long id); @Query("select count(s) from Student s join s.courses c where c.id=:id") long countByCourseId(@Param("id") Long id); }